import React, { useMemo } from 'react';
import { AbsoluteFill, Sequence, interpolate, staticFile, useCurrentFrame, useVideoConfig } from 'remotion';
import { Audio } from '@remotion/media';
import type { LineTiming, Scene, Storyboard } from '@dailies/core';
import { NARRATION_FILE, type ReelProps } from './config';
import { theme } from '../theme';
import { buildTimeline, lineAt } from '../timeline';
import { LIMITS, clampEnd, fitSize, textUnits } from './text';
import { ReelContext } from './ui';
import { Diff } from './scenes/Diff';
import { End } from './scenes/End';
import { Flag } from './scenes/Flag';
import { Prompt } from './scenes/Prompt';
import { Stats } from './scenes/Stats';
import { Terminal } from './scenes/Terminal';
import { Title } from './scenes/Title';

const { color, font, size, weight, leading, radius, space, stroke, layout, motion } = theme;

const SceneView: React.FC<{ scene: Scene }> = ({ scene }) => {
  switch (scene.type) {
    case 'title': return <Title scene={scene} />;
    case 'prompt': return <Prompt scene={scene} />;
    case 'terminal': return <Terminal scene={scene} />;
    case 'diff': return <Diff scene={scene} />;
    case 'stats': return <Stats scene={scene} />;
    case 'flag': return <Flag scene={scene} />;
    case 'end': return <End scene={scene} />;
  }
};

/** The line being spoken, drawn as a bar in the inset every scene keeps free for it. */
const CaptionBar: React.FC<{ storyboard: Storyboard; timings: LineTiming[]; audioStartFrame: number }> = ({ storyboard, timings, audioStartFrame }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const line = lineAt(storyboard, timings, (frame - audioStartFrame) / fps);
  if (!line) return null;
  const text = clampEnd(line.text, LIMITS.line);
  // The scenes keep room for three lines at the caption size; a longer line is set smaller rather than taller.
  const room = { width: layout.captionWidth - 2 * space.lg, height: 3 * size.caption * leading.text };
  const fontSize = fitSize(textUnits(text), room, { max: size.caption, min: size.label, advance: theme.advance.text, leading: leading.text });
  const since = frame - (audioStartFrame + line.startSec * fps);
  const shown = interpolate(since, [0, motion.enterSec * fps * 0.5], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  return (
    <AbsoluteFill style={{ justifyContent: 'flex-end', alignItems: 'center', paddingBottom: layout.captionBottom }}>
      <div
        style={{
          maxWidth: layout.captionWidth,
          padding: `${space.sm}px ${space.lg}px`,
          background: color.panel,
          border: `${stroke.hair}px solid ${color.edge}`,
          borderRadius: radius.md,
          color: color.text,
          fontFamily: font.text,
          fontSize,
          fontWeight: weight.medium,
          lineHeight: leading.text,
          textAlign: 'center',
          opacity: shown,
        }}
      >
        {text}
      </div>
    </AbsoluteFill>
  );
};

const Progress: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  return (
    <AbsoluteFill style={{ justifyContent: 'flex-end' }}>
      <div style={{ height: layout.progress, width: `${(frame / Math.max(1, durationInFrames - 1)) * 100}%`, background: color.accent }} />
    </AbsoluteFill>
  );
};

export const Reel: React.FC<ReelProps> = ({ storyboard, timings, audio }) => {
  const { fps } = useVideoConfig();
  const timeline = useMemo(() => buildTimeline(storyboard, timings, fps), [storyboard, timings, fps]);
  const context = useMemo(() => ({ repo: storyboard.repo, captions: !audio }), [storyboard.repo, audio]);
  return (
    <ReelContext.Provider value={context}>
      <AbsoluteFill style={{ background: theme.backdrop }}>
        {timeline.scenes.map((slot, i) => (
          <Sequence key={i} name={slot.sceneId} from={slot.startFrame} durationInFrames={slot.durationInFrames} premountFor={fps}>
            <SceneView scene={storyboard.scenes[i]!} />
          </Sequence>
        ))}
        {audio ? (
          <Sequence name="narration" from={timeline.audioStartFrame} layout="none">
            <Audio src={staticFile(NARRATION_FILE)} />
          </Sequence>
        ) : (
          <CaptionBar storyboard={storyboard} timings={timings} audioStartFrame={timeline.audioStartFrame} />
        )}
        <Progress />
      </AbsoluteFill>
    </ReelContext.Provider>
  );
};
import React from 'react';
import { spring } from 'remotion';
import { theme } from '../../theme';
import { LIMITS, clampEnd, fitSize, textUnits } from '../text';
import { Frame, Label, Rise, Rule, useContentBox, useMotion, type SceneOf } from '../ui';

const { color, font, size, weight, leading, tracking, radius, space, stroke, advance, motion } = theme;

// Shares of the content box the two texts may fill; the stamp row and the labels take the rest.
const QUOTE_SHARE = 0.33;
const REALITY_SHARE = 0.21;

export const Flag: React.FC<{ scene: SceneOf<'flag'> }> = ({ scene }) => {
  const m = useMotion();
  const box = useContentBox();
  const tone = scene.verdict === 'contradicted' ? color.bad : color.stale;
  const quote = clampEnd(scene.quote.trim(), LIMITS.flagQuote);
  const reality = clampEnd(scene.reality.trim(), LIMITS.flagReality);

  const quoteWidth = box.width - space.lg - stroke.bar;
  const quoteSize = fitSize(textUnits(quote) + 2, { width: quoteWidth, height: box.height * QUOTE_SHARE }, { ...size.claim, advance: advance.display, leading: leading.quote });
  const realitySize = fitSize(textUnits(reality), { width: box.width, height: box.height * REALITY_SHARE }, { ...size.reality, advance: advance.text, leading: leading.text });

  // The claim, then the record, then the stamp drops on the pair.
  const stampAt = m.settle * 0.6;
  const stamp = spring({ frame: m.frame - stampAt, fps: m.fps, config: motion.stamp, durationInFrames: Math.max(1, Math.round(m.settle - stampAt)) });

  return (
    <Frame label="Claim against the record">
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: space.lg }}>
        <Rise progress={m.span(0, 0.3)} style={{ display: 'flex', flexDirection: 'column', gap: space.sm }}>
          <Label>The agent wrote</Label>
          <div style={{ borderLeft: `${stroke.bar}px solid ${color.edge}`, paddingLeft: space.lg, fontFamily: font.display, fontStyle: 'italic', fontSize: quoteSize, lineHeight: leading.quote, letterSpacing: tracking.display, overflowWrap: 'anywhere' }}>
            “{quote}”
          </div>
        </Rise>
        <div style={{ display: 'flex', alignItems: 'center', gap: space.md, padding: `${space.sm}px 0` }}>
          <div
            style={{
              opacity: m.frame >= stampAt ? 1 : 0,
              transform: `rotate(${motion.stampTilt}deg) scale(${motion.stampFrom + (1 - motion.stampFrom) * stamp})`,
              border: `${stroke.bar}px solid ${tone}`,
              borderRadius: radius.sm,
              padding: `${space.xs}px ${space.md}px`,
              color: tone,
              fontFamily: font.text,
              fontSize: size.stamp,
              fontWeight: weight.medium,
              lineHeight: leading.text,
              letterSpacing: tracking.label,
              textTransform: 'uppercase',
              whiteSpace: 'nowrap',
            }}
          >
            {scene.verdict}
          </div>
          <div style={{ flex: 1 }}>
            <Rule progress={m.span(0.3, 0.6)} tone={tone} />
          </div>
        </div>
        <Rise progress={m.span(0.3, 0.6)} style={{ display: 'flex', flexDirection: 'column', gap: space.sm }}>
          <Label tone={tone}>The record shows</Label>
          <div style={{ fontSize: realitySize, fontWeight: weight.medium, lineHeight: leading.text, overflowWrap: 'anywhere' }}>{reality}</div>
        </Rise>
      </div>
    </Frame>
  );
};
import React from 'react';
import { interpolate } from 'remotion';
import { theme } from '../../theme';
import { LIMITS, clampEnd, fitSize, textUnits } from '../text';
import { Frame, Label, Rise, useContentBox, useMotion, type SceneOf } from '../ui';

const { color, font, size, leading, tracking, space, stroke, advance } = theme;

const SESSION_CHARS = 12;
const CLAMP = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;

export const Prompt: React.FC<{ scene: SceneOf<'prompt'> }> = ({ scene }) => {
  const m = useMotion();
  const box = useContentBox();
  const chars = Array.from(clampEnd(scene.quote.trim(), LIMITS.promptQuote));
  const footer = size.label * leading.text + space.lg;
  const fontSize = fitSize(textUnits(chars.join('')), { width: box.width - space.lg - stroke.bar, height: box.height - footer }, { ...size.quote, advance: advance.display, leading: leading.quote });

  // Typed on over the settle window. The untyped rest is laid out but invisible, so lines never re-wrap mid-word.
  const typed = Math.floor(interpolate(m.frame, [0, m.settle], [0, chars.length], CLAMP));
  const cursor = 1 - m.span(1, 1.2);

  return (
    <Frame label="The prompt">
      <div style={{ flex: 1, display: 'flex', alignItems: 'center' }}>
        <div style={{ borderLeft: `${stroke.bar}px solid ${color.accent}`, paddingLeft: space.lg, fontFamily: font.display, fontSize, lineHeight: leading.quote, letterSpacing: tracking.display, overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }}>
          <span>{chars.slice(0, typed).join('')}</span>
          <span style={{ borderRight: `${stroke.hair}px solid ${color.accent}`, marginRight: -stroke.hair, opacity: cursor }} />
          <span style={{ opacity: 0 }}>{chars.slice(typed).join('')}</span>
        </div>
      </div>
      <Rise progress={m.enter(1)} style={{ height: footer, display: 'flex', alignItems: 'flex-end', gap: space.md }}>
        <Label tone={color.accent}>Human prompt</Label>
        <div style={{ fontFamily: font.mono, fontSize: size.label, lineHeight: leading.text, color: color.muted }}>session {clampEnd(scene.sessionId, SESSION_CHARS)}</div>
      </Rise>
    </Frame>
  );
};

